def compute(vars):
    total_home_equity_loans = vars["v2"]
    high_ltv_home_equity_loans = vars["v1"]

    if total_home_equity_loans == 0:
        return None

    percentage = (high_ltv_home_equity_loans / total_home_equity_loans) * 100

    return {
        "value": percentage,
        "trace": {
            "high_ltv_home_equity_loans": high_ltv_home_equity_loans,
            "total_home_equity_loans": total_home_equity_loans,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
